double mat3_cofactor(const mat3& m, const int row, const int col) {
    // Calculate the 2x2 submatrix determinant after removing row and col
    int rows[2], cols[2];
    int r = 0, c = 0;

    // Find the two rows to keep
    for (int i = 0; i < 3; i++) {
        if (i != row) {
            rows[r++] = i;
        }
    }

    // Find the two columns to keep
    for (int j = 0; j < 3; j++) {
        if (j != col) {
            cols[c++] = j;
        }
    }

    // Calculate determinant of 2x2 submatrix
    double submatrix_det = m[rows[0]][cols[0]] * m[rows[1]][cols[1]] - m[rows[0]][cols[1]] * m[rows[1]][cols[0]];

    // Apply sign based on position: (-1)^(row + col)
    return ((row + col) % 2 == 0) ? submatrix_det : -submatrix_det;
}

